shared_code.value:
#include <string.h>

#include "ff.h"
#include "diskio.h"
#include "vfs.h"

#define VFS_TEST_FAT_SECTOR_SIZE            512U
#define VFS_TEST_FAT_SECTORS                256U

static uint8_t vfs_test_fat_disk[VFS_TEST_FAT_SECTOR_SIZE *
                                 VFS_TEST_FAT_SECTORS];
static DSTATUS vfs_test_fat_status = STA_NOINIT;
static vfs_fatfs_driver_c vfs_test_fat_driver;

#if VFS_CFG_USE_MUTUAL_EXCLUSION == TRUE
static THD_WORKING_AREA(vfs_test_fat_io_wa, 4096);
static THD_WORKING_AREA(vfs_test_fat_other_wa, 4096);
static thread_reference_t vfs_test_fat_waiter;
static bool vfs_test_fat_pause, vfs_test_fat_done;
static ssize_t vfs_test_fat_read_result;
static msg_t vfs_test_fat_stat_result;

static THD_FUNCTION(vfs_test_fat_reader, arg) {
  uint8_t buffer[VFS_TEST_FAT_SECTOR_SIZE];

  vfs_test_fat_read_result = vfsFileRead(arg, buffer, sizeof buffer);
}

static THD_FUNCTION(vfs_test_fat_other, arg) {
  vfs_stat_t stat;

  vfs_test_fat_stat_result = vfsNodeStat(arg, &stat);
  vfs_test_fat_done = true;
}
#endif

DSTATUS disk_initialize(BYTE pdrv) {

  if (pdrv != 0U) {
    return STA_NOINIT;
  }

  vfs_test_fat_status = 0U;
  return vfs_test_fat_status;
}

DSTATUS disk_status(BYTE pdrv) {

  if (pdrv != 0U) {
    return STA_NOINIT;
  }

  return vfs_test_fat_status;
}

DRESULT disk_read(BYTE pdrv, BYTE *buf, LBA_t sector, UINT count) {

  if ((pdrv != 0U) || ((vfs_test_fat_status & STA_NOINIT) != 0U)) {
    return RES_NOTRDY;
  }
  if ((count == 0U) || (sector >= VFS_TEST_FAT_SECTORS) ||
      ((LBA_t)count > (LBA_t)VFS_TEST_FAT_SECTORS - sector)) {
    return RES_PARERR;
  }

#if VFS_CFG_USE_MUTUAL_EXCLUSION == TRUE
  if (vfs_test_fat_pause) {
    vfs_test_fat_pause = false;
    chDbgAssert(chMtxGetNextMutexX() != NULL, "unprotected FatFS I/O");
    chSysLock();
    (void)chThdSuspendS(&vfs_test_fat_waiter);
    chSysUnlock();
  }
#endif
  memcpy(buf, &vfs_test_fat_disk[(size_t)sector *
                                 VFS_TEST_FAT_SECTOR_SIZE],
         (size_t)count * VFS_TEST_FAT_SECTOR_SIZE);
  return RES_OK;
}

DRESULT disk_write(BYTE pdrv, const BYTE *buf, LBA_t sector, UINT count) {

  if ((pdrv != 0U) || ((vfs_test_fat_status & STA_NOINIT) != 0U)) {
    return RES_NOTRDY;
  }
  if ((count == 0U) || (sector >= VFS_TEST_FAT_SECTORS) ||
      ((LBA_t)count > (LBA_t)VFS_TEST_FAT_SECTORS - sector)) {
    return RES_PARERR;
  }

  memcpy(&vfs_test_fat_disk[(size_t)sector * VFS_TEST_FAT_SECTOR_SIZE],
         buf, (size_t)count * VFS_TEST_FAT_SECTOR_SIZE);
  return RES_OK;
}

DRESULT disk_ioctl(BYTE pdrv, BYTE cmd, void *buf) {

  if ((pdrv != 0U) || ((vfs_test_fat_status & STA_NOINIT) != 0U)) {
    return RES_NOTRDY;
  }

  switch (cmd) {
  case CTRL_SYNC:
    return RES_OK;
  case GET_SECTOR_COUNT:
    *(LBA_t *)buf = (LBA_t)VFS_TEST_FAT_SECTORS;
    return RES_OK;
  case GET_SECTOR_SIZE:
    *(WORD *)buf = (WORD)VFS_TEST_FAT_SECTOR_SIZE;
    return RES_OK;
  case GET_BLOCK_SIZE:
    *(DWORD *)buf = 1U;
    return RES_OK;
  default:
    return RES_PARERR;
  }
}

DWORD get_fattime(void) {

  return ((DWORD)(2024U - 1980U) << 25) |
         ((DWORD)2U << 21) |
         ((DWORD)29U << 16) |
         ((DWORD)12U << 11) |
         ((DWORD)34U << 5) |
         ((DWORD)56U / 2U);
}

