                         chThdGetPriorityX() + 1, vfs_test_fat_other, second);
blocked = (vfs_test_fat_waiter != NULL) && !vfs_test_fat_done;
chThdResume(&vfs_test_fat_waiter, MSG_OK);
(void)chThdWait(reader);
(void)chThdWait(other);
